// Pick the first PDF or image attachment from the email and build the Gemini request.
const ALLOWED = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp'];
const MAX_BYTES = 15 * 1024 * 1024; // Gemini inline_data request limit is 20 MB
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const bin = item.binary || {};
  const key = Object.keys(bin).find((k) => ALLOWED.includes(bin[k].mimeType));
  if (!key) continue; // no invoice-like attachment: skip this email
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  if (buf.length > MAX_BYTES) continue;
  const prompt = $env.INVOICE_PROMPT || [
    'You extract structured data from one invoice, bill or receipt. Return only JSON with keys:',
    'vendor, vendor_tax_id, bill_to, invoice_number, issue_date (YYYY-MM-DD), due_date (YYYY-MM-DD), currency (ISO 4217),',
    'line_items [{description, quantity, unit_price, amount}], subtotal, tax_lines [{label (CGST|SGST|UTGST|IGST|VAT|Sales tax), rate, amount}],',
    'tax_total, total, payment_terms, confidence {same field names: number 0..1}, flags [string].',
    'Copy numbers exactly as printed, never recompute them. Use null for anything missing. Indian dates are day-first.',
  ].join(' ');
  out.push({ json: {
    message_id: item.json.id,
    from: item.json.from?.value?.[0]?.address || item.json.from || null,
    subject: item.json.subject || '',
    file_name: bin[key].fileName || key,
    request: {
      contents: [{ role: 'user', parts: [{ text: prompt }, { inline_data: { mime_type: bin[key].mimeType, data: buf.toString('base64') } }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0 },
    },
  } });
}
return out;

// Same checks, 0.85 floor and duplicate key as the invoice-extractor app (assets/core.js).
const FLOOR = Number($env.INVOICE_CONFIDENCE_FLOOR || 0.85);
const seen = $getWorkflowStaticData('global');
seen.keys = seen.keys || [];
const num = (v) => { if (v === null || v === undefined || v === '') return null; const n = Number(String(v).replace(/[^\d.\-]/g, '')); return Number.isFinite(n) ? n : null; };
const c = (n) => Math.round(Number(n) * 100);
const near = (a, b, tol = 1) => Math.abs(c(a) - c(b)) <= tol;
const iso = (s) => (/^\d{4}-\d{2}-\d{2}$/.test(String(s || '')) ? String(s) : null);
const dupKey = (inv) => {
  const v = String(inv.vendor || '').toLowerCase().replace(/\b(private|pvt|limited|ltd|inc|llc|llp|corp|co|company)\b\.?/g, '').replace(/[^a-z0-9]/g, '');
  const n = String(inv.invoice_number || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  return v && n ? v + '|' + n : null;
};

return $input.all().map((item, idx) => {
  const prep = $('Prepare attachment').all()[idx]?.json || {};
  let raw = {};
  try {
    const text = (item.json.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
    raw = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  } catch (e) { raw = {}; }
  const items = (raw.line_items || []).map((li) => ({ description: String(li.description || 'Item'), quantity: num(li.quantity), unit_price: num(li.unit_price), amount: num(li.amount) }));
  const tax = (raw.tax_lines || []).map((t) => ({ label: String(t.label || 'Tax'), rate: num(t.rate), amount: num(t.amount) })).filter((t) => t.amount !== null);
  const inv = {
    vendor: raw.vendor || null, vendor_tax_id: raw.vendor_tax_id || null, bill_to: raw.bill_to || null,
    invoice_number: raw.invoice_number ? String(raw.invoice_number) : null,
    issue_date: iso(raw.issue_date), due_date: iso(raw.due_date),
    currency: raw.currency ? String(raw.currency).toUpperCase().slice(0, 3) : null,
    line_items: items, subtotal: num(raw.subtotal), tax_lines: tax,
    tax_total: num(raw.tax_total) ?? (tax.length ? tax.reduce((s, t) => s + t.amount, 0) : null),
    total: num(raw.total), payment_terms: raw.payment_terms || null,
  };
  const checks = [];
  const add = (id, ok, detail) => checks.push({ id, status: ok === null ? 'skip' : ok ? 'pass' : 'fail', detail });
  const missing = ['vendor', 'invoice_number', 'issue_date', 'currency', 'subtotal', 'total'].filter((k) => inv[k] === null || inv[k] === undefined);
  add('required', !missing.length, missing.length ? 'Missing: ' + missing.join(', ') : 'ok');
  const priced = items.filter((li) => li.quantity !== null && li.unit_price !== null && li.amount !== null);
  add('line_math', priced.length ? priced.every((li) => near(li.quantity * li.unit_price, li.amount)) : null, priced.length + ' lines');
  const amounts = items.filter((li) => li.amount !== null);
  const sum = amounts.reduce((s, li) => s + c(li.amount), 0) / 100;
  add('items_sum', amounts.length && inv.subtotal !== null ? near(sum, inv.subtotal) : null, 'lines ' + sum + ' vs subtotal ' + inv.subtotal);
  const find = (k) => tax.find((t) => new RegExp('^' + k + '\\b', 'i').test(t.label));
  const cg = find('CGST'), sg = find('SGST') || find('UTGST'), ig = find('IGST');
  const taxOk = (inv.tax_total === null || near(tax.reduce((s, t) => s + c(t.amount), 0) / 100, inv.tax_total))
    && !(cg && sg && !near(cg.amount, sg.amount)) && !((cg || sg) && !(cg && sg)) && !(ig && (cg || sg))
    && tax.every((t) => !(inv.subtotal && t.rate) || near(inv.subtotal * t.rate / 100, t.amount, Math.max(1, items.length)));
  add('tax_breakdown', tax.length ? taxOk : null, tax.map((t) => t.label + ' ' + t.amount).join(', '));
  add('totals', inv.subtotal !== null && inv.total !== null ? near(inv.subtotal + (inv.tax_total || 0), inv.total) : null, inv.subtotal + ' + ' + (inv.tax_total || 0) + ' vs ' + inv.total);
  add('dates', !inv.issue_date ? false : !inv.due_date ? null : inv.due_date >= inv.issue_date, (inv.issue_date || '?') + ' -> ' + (inv.due_date || 'none'));
  const key = dupKey(inv);
  add('duplicate', key ? !seen.keys.includes(key) : null, key || 'no key');

  const conf = raw.confidence || {};
  const present = (k) => { const v = inv[k === 'tax_lines' ? 'tax_lines' : k]; return v !== null && v !== undefined && !(Array.isArray(v) && !v.length); };
  const fields = ['vendor', 'vendor_tax_id', 'bill_to', 'invoice_number', 'issue_date', 'due_date', 'currency', 'line_items', 'subtotal', 'tax_lines', 'tax_total', 'total', 'payment_terms'].filter(present);
  const scores = fields.map((k) => ({ k, v: Math.max(0, Math.min(1, Number(conf[k] ?? 0.5))) }));
  const min = scores.length ? scores.reduce((a, b) => (b.v < a.v ? b : a)) : { k: null, v: 0 };
  const failed = checks.filter((x) => x.status === 'fail').map((x) => x.id);
  const auto = !failed.length && min.v >= FLOOR;
  if (key && !seen.keys.includes(key)) { seen.keys.push(key); seen.keys = seen.keys.slice(-5000); }

  const t = (id) => tax.find((x) => new RegExp('^' + id + '\\b', 'i').test(x.label))?.amount ?? '';
  return { json: {
    auto_approve: auto,
    decision: auto ? 'auto_approve' : 'review',
    failed_checks: failed,
    low_confidence: scores.filter((s) => s.v < FLOOR).map((s) => s.k),
    min_confidence: Math.round(min.v * 100) / 100,
    flags: Array.isArray(raw.flags) ? raw.flags.slice(0, 6) : [],
    checks, invoice: inv, dup_key: key,
    row: {
      received_at: new Date().toISOString(), from: prep.from, file: prep.file_name,
      vendor: inv.vendor, vendor_tax_id: inv.vendor_tax_id, invoice_number: inv.invoice_number,
      issue_date: inv.issue_date, due_date: inv.due_date, currency: inv.currency,
      subtotal: inv.subtotal, cgst: t('CGST'), sgst: t('SGST'), igst: t('IGST'), tax_total: inv.tax_total,
      total: inv.total, payment_terms: inv.payment_terms, min_confidence: Math.round(min.v * 100) / 100,
    },
    message_id: prep.message_id, subject: prep.subject,
  } };
});
